#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    const char *s;
    size_t pos;
} Parser;

static void skip_sep(Parser *p) {
    while (p->s[p->pos] == ' ' || p->s[p->pos] == ',') p->pos++;
}

static int parse_int(Parser *p) {
    skip_sep(p);
    int sign = 1;
    if (p->s[p->pos] == '-') {
        sign = -1;
        p->pos++;
    }
    int value = 0;
    while (p->s[p->pos] >= '0' && p->s[p->pos] <= '9') {
        value = value * 10 + (p->s[p->pos] - '0');
        p->pos++;
    }
    return sign * value;
}

static void expect(Parser *p, char ch) {
    while (p->s[p->pos] == ' ') p->pos++;
    if (p->s[p->pos] != ch) exit(2);
    p->pos++;
}

static int *parse_row(Parser *p, int *size) {
    expect(p, '[');
    int cap = 8;
    int count = 0;
    int *row = (int *)malloc((size_t)cap * sizeof(int));
    if (row == NULL) exit(3);

    skip_sep(p);
    while (p->s[p->pos] != ']') {
        if (count == cap) {
            cap *= 2;
            int *tmp = (int *)realloc(row, (size_t)cap * sizeof(int));
            if (tmp == NULL) exit(3);
            row = tmp;
        }
        row[count++] = parse_int(p);
        skip_sep(p);
    }
    p->pos++;
    *size = count;
    return row;
}

static int **parse_grid(Parser *p, int *rows, int **cols) {
    expect(p, '[');
    int row_cap = 8;
    int row_count = 0;
    int **grid = (int **)malloc((size_t)row_cap * sizeof(int *));
    int *grid_cols = (int *)malloc((size_t)row_cap * sizeof(int));
    if (grid == NULL || grid_cols == NULL) exit(3);

    skip_sep(p);
    while (p->s[p->pos] != ']') {
        if (row_count == row_cap) {
            row_cap *= 2;
            int **new_grid = (int **)realloc(grid, (size_t)row_cap * sizeof(int *));
            int *new_cols = (int *)realloc(grid_cols, (size_t)row_cap * sizeof(int));
            if (new_grid == NULL || new_cols == NULL) exit(3);
            grid = new_grid;
            grid_cols = new_cols;
        }
        grid[row_count] = parse_row(p, &grid_cols[row_count]);
        row_count++;
        skip_sep(p);
    }
    p->pos++;

    *rows = row_count;
    *cols = grid_cols;
    return grid;
}

static void swap_flat(int **grid, int n, int a, int b) {
    int ar = a / n, ac = a % n;
    int br = b / n, bc = b % n;
    int tmp = grid[ar][ac];
    grid[ar][ac] = grid[br][bc];
    grid[br][bc] = tmp;
}

static void reverse_flat(int **grid, int n, int left, int right) {
    while (left < right) {
        swap_flat(grid, n, left, right);
        left++;
        right--;
    }
}

