    reverse_flat(grid, n, 0, total - 1);
    reverse_flat(grid, n, 0, k - 1);
    reverse_flat(grid, n, k, total - 1);

    int *cols = (int *)malloc((size_t)m * sizeof(int));
    if (cols == NULL) exit(3);
    for (int i = 0; i < m; i++) cols[i] = n;

    *returnSize = m;
    *returnColumnSizes = cols;
    return grid;
