using namespace std;

struct Parser {
    const string &s;
    size_t pos = 0;

    void skip() {
        while (pos < s.size() && (s[pos] == ' ' || s[pos] == ',')) pos++;
    }

    void expect(char ch) {
        while (pos < s.size() && s[pos] == ' ') pos++;
        if (pos >= s.size() || s[pos] != ch) throw runtime_error("parse error");
        pos++;
    }

    int parseInt() {
        skip();
        int sign = 1;
        if (s[pos] == '-') {
            sign = -1;
            pos++;
        }
        int value = 0;
        while (pos < s.size() && s[pos] >= '0' && s[pos] <= '9') {
            value = value * 10 + (s[pos] - '0');
            pos++;
        }
        return sign * value;
    }

    vector<int> parseRow() {
        expect('[');
        vector<int> row;
        skip();
        while (s[pos] != ']') {
            row.push_back(parseInt());
            skip();
        }
        pos++;
        return row;
    }

    vector<vector<int>> parseGrid() {
        expect('[');
        vector<vector<int>> grid;
        skip();
        while (s[pos] != ']') {
            grid.push_back(parseRow());
            skip();
        }
        pos++;
        return grid;
    }
};

// ---------------------------------------------------------------------
