class Solution {
public:
    vector<vector<int>> shiftGrid(vector<vector<int>>& grid, int k) {
        int m = static_cast<int>(grid.size());
        int n = static_cast<int>(grid[0].size());
        int total = m * n;
        k %= total;

        auto swapFlat = [&](int a, int b) {
            int ar = a / n, ac = a % n;
            int br = b / n, bc = b % n;
            swap(grid[ar][ac], grid[br][bc]);
        };

        auto reverseFlat = [&](int left, int right) {
            while (left < right) {
                swapFlat(left, right);
                left++;
                right--;
            }
        };

        reverseFlat(0, total - 1);
        reverseFlat(0, k - 1);
        reverseFlat(k, total - 1);
        return grid;
    }
};

int main() {
    string line;
    getline(cin, line);

    Parser p{line};
    p.expect('[');
    vector<vector<int>> grid = p.parseGrid();
    p.expect(',');
    int k = p.parseInt();
    p.expect(']');

    vector<vector<int>> result = Solution().shiftGrid(grid, k);

    cout << '[';
    for (size_t r = 0; r < result.size(); r++) {
        if (r) cout << ',';
        cout << '[';
        for (size_t c = 0; c < result[r].size(); c++) {
            if (c) cout << ',';
            cout << result[r][c];
        }
        cout << ']';
    }
    cout << "]\n";
    return 0;
}

