import java.io.*;
import java.util.*;

class Solution {
    public List<List<Integer>> shiftGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int total = m * n;
        k %= total;

        reverse(grid, n, 0, total - 1);
        reverse(grid, n, 0, k - 1);
        reverse(grid, n, k, total - 1);

        List<List<Integer>> result = new ArrayList<>(m);
        for (int r = 0; r < m; r++) {
            List<Integer> row = new ArrayList<>(n);
            for (int c = 0; c < n; c++) {
                row.add(grid[r][c]);
            }
            result.add(row);
        }
        return result;
    }

    private void reverse(int[][] grid, int n, int left, int right) {
        while (left < right) {
            swap(grid, n, left, right);
            left++;
            right--;
        }
    }

    private void swap(int[][] grid, int n, int a, int b) {
        int ar = a / n, ac = a % n;
        int br = b / n, bc = b % n;
        int tmp = grid[ar][ac];
        grid[ar][ac] = grid[br][bc];
        grid[br][bc] = tmp;
    }
}

public class Main {
    private static String raw;
    private static int pos;

    private static void skipSeparators() {
        while (pos < raw.length() && (raw.charAt(pos) == ' ' || raw.charAt(pos) == ',')) pos++;
    }

    private static String nextToken() {
        skipSeparators();
        int start = pos;
        if (raw.charAt(pos) == '[') {
            int depth = 0;
            while (pos < raw.length()) {
                char ch = raw.charAt(pos++);
                if (ch == '[') depth++;
                else if (ch == ']') {
                    depth--;
                    if (depth == 0) break;
                }
            }
            return raw.substring(start, pos);
        }
        while (pos < raw.length() && raw.charAt(pos) != ',') pos++;
        return raw.substring(start, pos).trim();
    }

    private static List<int[]> parseRows(String s) {
        List<int[]> rows = new ArrayList<>();
        int i = 1;
        while (i < s.length() - 1) {
            while (i < s.length() - 1 && (s.charAt(i) == ' ' || s.charAt(i) == ',')) i++;
            if (i >= s.length() - 1) break;
            int start = i;
            int depth = 0;
            while (i < s.length() - 1) {
                char ch = s.charAt(i++);
                if (ch == '[') depth++;
                else if (ch == ']') {
                    depth--;
                    if (depth == 0) break;
                }
            }
            String row = s.substring(start, i);
            rows.add(parseRow(row));
        }
        return rows;
    }

    private static int[] parseRow(String s) {
        if (s.equals("[]")) return new int[0];
        String inner = s.substring(1, s.length() - 1);
        String[] parts = inner.split(",");
        int[] row = new int[parts.length];
        for (int i = 0; i < parts.length; i++) row[i] = Integer.parseInt(parts[i].trim());
        return row;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        raw = line.substring(1, line.length() - 1);
        pos = 0;

        String gridToken = nextToken();
        int k = Integer.parseInt(nextToken());

        List<int[]> rows = parseRows(gridToken);
        int[][] grid = rows.toArray(new int[0][]);

        List<List<Integer>> result = new Solution().shiftGrid(grid, k);
        StringBuilder out = new StringBuilder("[");
        for (int r = 0; r < result.size(); r++) {
            if (r > 0) out.append(',');
            out.append('[');
            for (int c = 0; c < result.get(r).size(); c++) {
                if (c > 0) out.append(',');
                out.append(result.get(r).get(c));
            }
            out.append(']');
        }
        out.append(']');
        System.out.println(out);
    }
}

